import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { usePeople, type Person } from '../people/usePeople';
import { poolsKey, usePools, type Pool } from './usePools';

// The sheet's pools and the form that adds one (a blank name, or one already a pool, is refused). Each
// pool lists its members with their shares, its total share (a retired member counting 0.00) and whether
// it is balanced (the total is exactly 100.00), and adds a member from its row: a person already in the
// pool, or a share not more than 0.00 and at most 100.00 with two decimals, is refused. Each member of a balanced
// pool shows their cut of its pot (empty while the pool is unbalanced or has no pot). A member may be another pool,
// chosen as pool:<name>: a pool is a member of at most one pool, never contains itself through any chain, and a chain
// of pools is at most three deep. A pool that is a member of none has the sheet's pot; a pool that is a member of
// another has its cut there as its pot. A membership may carry an optional from-date and to-date (a to-date before
// the from-date is refused); a member whose dates do not include the sheet's today is left out entirely: not in the
// total share, not in the balance, no cut.
export function PoolPanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const pools = usePools(sheet);
  const people = usePeople(sheet);
  const [name, setName] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { name: string }) =>
      postJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`, { ...body, user }),
    onSuccess: (saved) => {
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A pool member: the person's id and name (or, for another pool that is a member, personId null and memberPool its
 *  name), their share percent (two decimals) and whether a retirement date is set (a retired member's share counts
 *  0.00 toward the total), and their cut of the pool's pot (two decimals; "" when the pool is not balanced or has no
 *  pot). current: whether the membership's optional from- and to-dates include the sheet's today; a member not
 *  current is left out entirely: not in the total, not in the balance, no cut (""). A pool that is a member of none has the sheet's pot; one that is a member of another has its cut there. */
export type PoolMember = { personId: string | null; memberPool: string | null; name: string; share: string; retired: boolean; current: boolean; cut: string };

/** A pool: its members in the order added, the total of their shares and whether that is exactly 100.00. */
export type Pool = { name: string; totalShare: string; balanced: boolean; members: PoolMember[] };
